    import subprocess
    try:
        res = subprocess.run(['pdftotext', '-f', '1', '-l', '1', path, '-'], capture_output=True, text=True)
        return res.stdout.lower()
    except: return ''

def get_docx_text(path):
    try:
        with zipfile.ZipFile(path) as z:
            with z.open('word/document.xml') as f:
                tree = ET.parse(f)
                return ' '.join([node.text for node in tree.iter() if node.text]).lower()
    except: return ''

def get_pptx_text(path):
    try:
        with zipfile.ZipFile(path) as z:
            with z.open('ppt/slides/slide1.xml') as f:
                tree = ET.parse(f)
                return ' '.join([node.text for node in tree.iter() if node.text]).lower()
    except: return ''

categories = {
    'LLM': ['llm', 'large language model', 'gpt', 'wizardcoder', 'jais', 'instruction mixing', 'pediatricsgpt', 'lola', 'reasoning models'],
